      yPercent: -50 * speed,
      ease: 'none',
      scrollTrigger: {
        trigger: element,
        start: 'top bottom',
        end: 'bottom top',
        scrub: true
      }
    });
  });
};

// Refresh ScrollTrigger
export const refreshScrollTrigger = () => {
  setTimeout(() => {
    ScrollTrigger.refresh();
  }, 100);
};

// Kill all ScrollTrigger instances
export const killScrollTrigger = () => {
  ScrollTrigger.killAll();
};

